impl AntiRejectViaHorizonFrom<MultiVector> for Horizon {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        4       11        0
    //    simd2        0        2        0
    //    simd3        3        9        0
    //    simd4        2        8        0
    // Totals...
    // yes simd        9       30        0
    //  no simd       21       74        0
    fn anti_reject_via_horizon_from(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let wedge_g0 = Simd32x2::from([1.0, self[e3215] * other[e4]]) * Simd32x2::from([0.0, 1.0]);
        let wedge_g10 = self[e3215] * other[scalar];
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g1 = other.group9().yzwx() * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g3 = other.group7().with_w(other[e321] * -1.0);
        let right_dual_g6 = other.group5().with_w(other[e45]) * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        return MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (wedge_g10 * right_dual_g1[3]) + (right_dual_g0[0] * wedge_g0[1]) + (right_dual_g0[1] * wedge_g0[0]),
                right_dual_g0[1] * wedge_g0[1],
            ]),
            // e1, e2, e3, e4
            (right_dual_g1 * Simd32x4::from(wedge_g0[1])) - (Simd32x3::from(wedge_g10) * right_dual_g3.xyz()).with_w(0.0),
            // e5
            (wedge_g0[1] * other[e3215]) - (wedge_g10 * right_dual_g3[3]),
            // e41, e42, e43, e45
            right_dual_g3 * Simd32x4::from(wedge_g0[1]),
            // e15, e25, e35
            (Simd32x3::from(wedge_g10) * right_dual_g6.xyz()) + (Simd32x3::from(wedge_g0[1]) * other.group8()),
            // e23, e31, e12
            (right_dual_g7 * Simd32x3::from(wedge_g10)) + (Simd32x3::from(wedge_g0[1]) * other.group6().xyz()),
            // e415, e425, e435, e321
            (right_dual_g6 * Simd32x4::from(wedge_g0[1])) - (right_dual_g9.wyzx() * Simd32x3::from(0.0).with_w(wedge_g10)),
            // e423, e431, e412
            right_dual_g7 * Simd32x3::from(wedge_g0[1]),
            // e235, e315, e125
            -(Simd32x3::from(wedge_g10) * right_dual_g9.yzw()) - (Simd32x3::from(wedge_g0[1]) * other.group4()),
            // e1234, e4235, e4315, e4125
            right_dual_g9 * Simd32x4::from(wedge_g0[1]),
            // e3215
            (wedge_g10 * right_dual_g0[1]) - (wedge_g0[1] * other[e5]),
        );
    }
}
